CREATE TABLE tariff_plans (
    plan_id SERIAL PRIMARY KEY,
    plan_name VARCHAR(100) NOT NULL,
    monthly_fee DECIMAL(10,2) NOT NULL,
    minutes_included INT DEFAULT 0,
    sms_included INT DEFAULT 0,
    data_gb_included INT DEFAULT 0,
    price_per_minute DECIMAL(5,2) DEFAULT 1.50,
    price_per_sms DECIMAL(5,2) DEFAULT 2.00,
    price_per_gb DECIMAL(5,2) DEFAULT 150.00,
    is_active BOOLEAN DEFAULT TRUE
);

CREATE TABLE service_types (
    service_type_id SERIAL PRIMARY KEY,
    service_name VARCHAR(50) NOT NULL,
    description VARCHAR(200)
);


CREATE TABLE subscribers (
    subscriber_id SERIAL PRIMARY KEY,
    phone_number VARCHAR(15) UNIQUE NOT NULL,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    email VARCHAR(100),
    plan_id INT REFERENCES tariff_plans(plan_id),
    registration_date DATE DEFAULT CURRENT_DATE,
    status VARCHAR(20) DEFAULT 'ACTIVE',
    balance DECIMAL(10,2) DEFAULT 0.00,
    CONSTRAINT chk_status CHECK (status IN ('ACTIVE', 'SUSPENDED', 'TERMINATED'))
);

CREATE TABLE call_records (
    record_id BIGSERIAL PRIMARY KEY,
    subscriber_id INT NOT NULL REFERENCES subscribers(subscriber_id),
    service_type_id INT REFERENCES service_types(service_type_id),
    call_date TIMESTAMP NOT NULL,
    destination_number VARCHAR(15),
    duration_seconds INT,
    quantity INT DEFAULT 1,
    cost DECIMAL(10,2) DEFAULT 0.00
);

CREATE TABLE data_usage (
    usage_id BIGSERIAL PRIMARY KEY,
    subscriber_id INT NOT NULL REFERENCES subscribers(subscriber_id),
    usage_date DATE NOT NULL,
    data_mb BIGINT NOT NULL,
    cost DECIMAL(10,2) DEFAULT 0.00
);

CREATE TABLE invoices (
    invoice_id SERIAL PRIMARY KEY,
    subscriber_id INT NOT NULL REFERENCES subscribers(subscriber_id),
    billing_period VARCHAR(7) NOT NULL,
    issue_date DATE DEFAULT CURRENT_DATE,
    due_date DATE,
    monthly_fee DECIMAL(10,2) DEFAULT 0.00,
    usage_charges DECIMAL(10,2) DEFAULT 0.00,
    total_amount DECIMAL(10,2) NOT NULL,
    status VARCHAR(20) DEFAULT 'PENDING',
    CONSTRAINT chk_invoice_status CHECK (status IN ('PENDING', 'PAID', 'OVERDUE', 'CANCELLED'))
);

CREATE TABLE payments (
    payment_id SERIAL PRIMARY KEY,
    subscriber_id INT NOT NULL REFERENCES subscribers(subscriber_id),
    invoice_id INT REFERENCES invoices(invoice_id),
    payment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    amount DECIMAL(10,2) NOT NULL,
    payment_method VARCHAR(30),
    transaction_id VARCHAR(100)
);

CREATE TABLE plan_changes (
    change_id SERIAL PRIMARY KEY,
    subscriber_id INT NOT NULL REFERENCES subscribers(subscriber_id),
    old_plan_id INT REFERENCES tariff_plans(plan_id),
    new_plan_id INT REFERENCES tariff_plans(plan_id),
    change_date DATE DEFAULT CURRENT_DATE,
    reason VARCHAR(200)
);









CREATE INDEX idx_subscribers_phone ON subscribers(phone_number);
CREATE INDEX idx_subscribers_plan ON subscribers(plan_id);
CREATE INDEX idx_subscribers_status ON subscribers(status);

CREATE INDEX idx_call_records_subscriber ON call_records(subscriber_id);
CREATE INDEX idx_call_records_date ON call_records(call_date);
CREATE INDEX idx_call_records_service ON call_records(service_type_id);

CREATE INDEX idx_data_usage_subscriber ON data_usage(subscriber_id);
CREATE INDEX idx_data_usage_date ON data_usage(usage_date);

CREATE INDEX idx_invoices_subscriber ON invoices(subscriber_id);
CREATE INDEX idx_invoices_period ON invoices(billing_period);
CREATE INDEX idx_invoices_status ON invoices(status);

CREATE INDEX idx_payments_subscriber ON payments(subscriber_id);
CREATE INDEX idx_payments_invoice ON payments(invoice_id);
CREATE INDEX idx_payments_date ON payments(payment_date);

ANALYZE tariff_plans;
ANALYZE service_types;
ANALYZE subscribers;
ANALYZE call_records;
ANALYZE data_usage;
ANALYZE invoices;
ANALYZE payments;
ANALYZE plan_changes;

